              set[j].semver.minor === sv.minor &&
              set[j].semver.patch === sv.patch) {
              pass = true
              break
            }
          }
        }
        ok = pass
      }
    }
    if (ok) {
      if (!max || maxSV.compare(v) === -1) {
        max = v
        maxSV = new SemVer(max, options)
      }
    }
  })
  return max
}

